const FIXED_MONSTERS = [
  ...FIXED_RARE_MONSTERS,
  ...ALL_FIXED_BOSS_MONSTERS,
  ...FIXED_SPECIAL_BOSSES,
  ...CHEST_TRAP_MONSTERS,
  ...STORY_EVENT_MONSTERS,
];

const NORMAL_MONSTER_BASES = MONSTER_BANDS_1_200.flatMap((band) => band.monsters);

const ALL_MONSTER_BASES = [
  ...NORMAL_MONSTER_BASES,
  ...FIXED_MONSTERS,
];

// モンスターマスターの命中は絶対値（100 = 基準命中）へ統一する。
// 旧データでは 0 が基準100、1～49が「100への加算値」として混在していたため、
// 読み込み時に正規化し、図鑑・戦闘・エディタの解釈を一致させる。
function normalizeMonsterHitRate(rawValue, fallback = 100) {
  const value = Number(rawValue);
  const base = Math.max(1, Number(fallback) || 100);
  if (!Number.isFinite(value) || value <= 0) return base;
  if (value < 50) return base + value;
  return value;
}

ALL_MONSTER_BASES.forEach((monster) => {
  if (!monster) return;
  monster.hit = normalizeMonsterHitRate(monster.hit, 100);
});

const monsters = ALL_MONSTER_BASES;

function cloneMonsterData(monster) {
  return monster ? JSON.parse(JSON.stringify(monster)) : null;
}

function getFloorOffset(floor, band) {
  const index = Math.max(0, Math.min(4, floor - band.bandStart));

  if (band.offsetType === 'low_1_5') {
    return LOW_FLOOR_OFFSETS[1][index];
  }

  if (band.offsetType === 'low_6_10') {
    return LOW_FLOOR_OFFSETS[6][index];
  }

  return STANDARD_FLOOR_OFFSETS[index];
}

function applyFloorOffset(baseMonster, floor, band) {
  const offset = getFloorOffset(floor, band);
  const monster = cloneMonsterData(baseMonster);

  monster.hp = Math.floor(monster.hp * offset.hpMp);
  monster.mp = Math.floor(monster.mp * offset.hpMp);
  monster.atk = Math.floor(monster.atk * offset.other);
  monster.def = Math.floor(monster.def * offset.other);
  monster.spd = Math.floor(monster.spd * offset.other);
  monster.mag = Math.floor(monster.mag * offset.other);
  monster.mdef = Math.floor(monster.mdef * offset.other);
  monster.gold = Math.floor(monster.gold * offset.reward);
  monster.exp = Math.floor(monster.exp * offset.reward);

  monster.baseId = baseMonster.id;
  monster.generatedFloor = floor;
  monster.isBandMonster = true;

  return monster;
}


function normalizeEncounterFloor(value, fallback = 0) {
  const floor = Number(value);
  return Number.isFinite(floor) ? Math.max(0, Math.floor(floor)) : fallback;
}

function matchesFloorRanges(ranges, floor) {
  if (!Array.isArray(ranges) || ranges.length === 0) return true;
  const value = normalizeEncounterFloor(floor, 0);
  return ranges.some((range) => {
    if (Number.isFinite(Number(range))) return value === Number(range);
    const from = normalizeEncounterFloor(range?.from ?? range?.start, 0);
    const to = normalizeEncounterFloor(range?.to ?? range?.end ?? from, from);
    return value >= Math.min(from, to) && value <= Math.max(from, to);
  });
}

function getEncounterCandidates(options = {}) {
  const mapId = String(options.mapId || '').trim();
  const floor = normalizeEncounterFloor(options.floor, 0);
  const hasSection = options.section !== null && options.section !== undefined && options.section !== '';
  const section = hasSection ? normalizeEncounterFloor(options.section, 0) : null;
  const abyssFloor = normalizeEncounterFloor(options.abyssFloor, 0);
  // rankMin / rankMax are optional. Runtime battle data stores an omitted bound as null;
  // Number(null) === 0, so coercing first would incorrectly turn every habitat encounter
  // into an explicit Rank 1 range and bypass monsters.js habitat matching entirely.
  const hasRankMin = options.rankMin !== null && options.rankMin !== undefined && options.rankMin !== '';
  const hasRankMax = options.rankMax !== null && options.rankMax !== undefined && options.rankMax !== '';
  const rankMinRaw = hasRankMin ? Number(options.rankMin) : NaN;
  const rankMaxRaw = hasRankMax ? Number(options.rankMax) : NaN;
  const hasRankRange = Number.isFinite(rankMinRaw) || Number.isFinite(rankMaxRaw);
  const rankMin = Number.isFinite(rankMinRaw) ? Math.max(1, Math.floor(rankMinRaw)) : 1;
  const rankMax = Number.isFinite(rankMaxRaw) ? Math.max(rankMin, Math.floor(rankMaxRaw)) : Infinity;
  const raceSet = new Set((Array.isArray(options.races) ? options.races : (options.race ? [options.race] : []))
    .map(value => String(value || '').trim()).filter(Boolean));
  return NORMAL_MONSTER_BASES.filter((monster) => {
    if (raceSet.size > 0 && !raceSet.has(String(monster?.race || ''))) return false;
    if (abyssFloor > 0) return matchesFloorRanges(monster.abyssFloors, abyssFloor) && Array.isArray(monster.abyssFloors) && monster.abyssFloors.length > 0;
    if (hasRankRange) {
      const rank = Math.max(1, Number(monster?.rank || monster?.minF || 1));
      return rank >= rankMin && rank <= rankMax;
    }
    if (!mapId) return false;
    return (monster.habitats || []).some((habitat) => {
      if (String(habitat?.mapId || '') !== mapId) return false;
      if (Array.isArray(habitat?.sections) && habitat.sections.length > 0) {
        return hasSection && matchesFloorRanges(habitat.sections, section);
      }
      return matchesFloorRanges(habitat?.floors, floor);
    });
  });
}

function generateEnemyForEncounter(options = {}) {
  const allowRare = options.allowRare !== false;
  const abyssFloor = normalizeEncounterFloor(options.abyssFloor, 0);
  const rankFallback = Math.max(1, normalizeEncounterFloor(options.rank, normalizeEncounterFloor(options.floor, 1)));

  if (allowRare) {
    const rare = tryGenerateRareMonster(rankFallback);
    if (rare) return rare;
  }

  const candidates = getEncounterCandidates(options);
  if (candidates.length > 0) {
    const base = candidates[Math.floor(Math.random() * candidates.length)];
    if (abyssFloor > 0 && abyssFloor <= 100) {
      const effectiveRank = 100 + abyssFloor;
      const band = getMonsterBandForFloor(effectiveRank) || getMonsterBandForFloor(base.rank);
      return band ? applyFloorOffset(base, effectiveRank, band) : cloneMonsterData(base);
    }
    return cloneMonsterData(base);
  }

  // Existing Abyss floors beyond the newly specified 01-100 table retain the prior rank-based behavior.
  return generateEnemyForFloor(rankFallback, { allowRare: false });
}

function getHabitatLabels(monsterOrId) {
  const monster = typeof monsterOrId === 'object' ? monsterOrId : getMonsterById(monsterOrId);
  if (!monster) return [];

  const mapName = (mapId) => {
    const registryName = globalThis.MapRegistry?.getMapName?.(mapId);
    if (registryName) return registryName;
    const defs = globalThis.MAP_MASTER || {};
    const entry = Object.values(defs).find((value) => String(value?.id) === String(mapId));
    return entry?.name || String(mapId || '不明');
  };

  // 図鑑の階層表記を全MAPで統一する。
  // 0階は「周辺」「海上」など階層を持たないエリアを表すため表示しない。
  const rangeLabel = (range) => {
    const from = normalizeEncounterFloor(range?.from ?? range?.start ?? range, 0);
    const to = normalizeEncounterFloor(range?.to ?? range?.end ?? from, from);
    if (from === 0 && to === 0) return '';
    return from === to ? `${from}階` : `${from}～${to}階`;
  };

  const formatAreaLabel = (name, ranges) => {
    const floors = Array.isArray(ranges) ? ranges.map(rangeLabel).filter(Boolean) : [];
    return `${name}${floors.length ? `（${floors.join('・')}）` : ''}`;
  };

  const shouldShowHabitat = (mapId) => {
    const registryDecision = globalThis.MapRegistry?.shouldShowMonsterHabitatInEncyclopedia?.(mapId);
    if (registryDecision === false) return false;
    if (registryDecision === true) return true;
    const defs = globalThis.MAP_MASTER || {};
    const entry = Object.values(defs).find((value) => String(value?.id) === String(mapId));
    return entry?.showMonsterHabitatInEncyclopedia !== false;
  };

  const labels = [];
  (monster.habitats || []).forEach((habitat) => {
    if (!shouldShowHabitat(habitat?.mapId)) return;
    if (Array.isArray(habitat?.sections) && habitat.sections.length > 0) {
      const sections = globalThis.MapRegistry?.getMapSections?.(habitat?.mapId) || [];
      const names = sections
        .filter((entry) => matchesFloorRanges(habitat.sections, entry.section))
        .map((entry) => entry.name)
        .filter(Boolean);
      if (names.length > 0) {
        labels.push(...names);
        return;
      }
    }
    labels.push(formatAreaLabel(mapName(habitat?.mapId), habitat?.floors));
  });

  // 深淵も通常MAPと同じ「エリア名（○～○階）」形式で表示する。
  // 例: 深淵（101～105階）
  if (Array.isArray(monster.abyssFloors) && monster.abyssFloors.length > 0) {
    const abyssMapId = globalThis.MAP_IDS?.ABYSS || 'MAP000033';
    if (shouldShowHabitat(abyssMapId)) {
      labels.push(formatAreaLabel(mapName(abyssMapId), monster.abyssFloors));
    }
  }

  return Array.from(new Set(labels.filter(Boolean)));
}

function getMonsterBandForFloor(floor) {
  return MONSTER_BANDS_1_200.find((band) => floor >= band.bandStart && floor <= band.bandEnd) || null;
}

function generateBandMonster(floor) {
  const band = getMonsterBandForFloor(floor);

  if (!band || !band.monsters || band.monsters.length === 0) {
    return null;
  }

  const base = band.monsters[Math.floor(Math.random() * band.monsters.length)];
  return applyFloorOffset(base, floor, band);
}

function isStoryQuestBossId(monsterOrId) {
  const id = Number(typeof monsterOrId === 'object' ? monsterOrId?.id : monsterOrId);
  return Number.isFinite(id) && id >= 300000 && id < 400000;
}

function isAbyssRandomBossCandidate(monster) {
  const id = Number(monster?.id);
  return Number.isFinite(id) && id >= 400000 && id < 500000;
}

function getBossesForFloor(floor) {
  return ALL_FIXED_BOSS_MONSTERS
    .filter((monster) => monster.isBoss && !monster.isRare && !monster.isEstark && !monster.isSpecialBoss && isAbyssRandomBossCandidate(monster) && monster.minF === floor)
    .map(cloneMonsterData);
}

function getSpecialBossesForFloor(floor) {
  return FIXED_SPECIAL_BOSSES
    .filter((monster) => monster.isBoss && (monster.isSpecialBoss || monster.isEstark) && monster.minF === floor)
    .map(cloneMonsterData);
}

function getBossesByIds(ids) {
  const idList = Array.isArray(ids) ? ids : [ids];

  return idList
    .map((id) => ALL_MONSTER_BASES.find((monster) => monster.id === normalizeMonsterId(id)))
    .filter(Boolean)
    .map(cloneMonsterData);
}

const RARE_ENCOUNTER_RANK_BANDS = Object.freeze([
  Object.freeze({ from: 31, to: 70, monsterId: 200201 }),
  Object.freeze({ from: 71, to: 105, monsterId: 200202 }),
  Object.freeze({ from: 106, to: 150, monsterId: 200203 }),
  Object.freeze({ from: 151, to: Infinity, monsterId: 200204 })
]);
const RARE_ENCOUNTER_RATE = 0.03;

function getRareMonsterIdForRank(rank) {
  const value = Math.max(1, Math.floor(Number(rank) || 1));
  return RARE_ENCOUNTER_RANK_BANDS.find(band => value >= band.from && value <= band.to)?.monsterId || null;
}

function getRareCandidatesForRank(rank) {
  const id = getRareMonsterIdForRank(rank);
  if (id === null) return [];
  const monster = FIXED_RARE_MONSTERS.find((m) => m.id === id);
  return monster ? [monster] : [];
}

function getRareCandidatesForFloor(floor) {
  return getRareCandidatesForRank(floor);
}

function getRareEncounterRateForRank(rank) {
  return getRareMonsterIdForRank(rank) === null ? 0 : RARE_ENCOUNTER_RATE;
}

function getRareEncounterRate(floor) {
  return getRareEncounterRateForRank(floor);
}

function tryGenerateRareMonster(rank, options = {}) {
  const explicitIds = Array.isArray(options.candidateIds)
    ? options.candidateIds.map(Number).filter(Number.isFinite)
    : [];
  const candidates = explicitIds.length > 0
    ? FIXED_RARE_MONSTERS.filter(monster => explicitIds.includes(Number(monster?.id)))
    : (options.allCandidates === true ? FIXED_RARE_MONSTERS : getRareCandidatesForRank(rank));

  if (candidates.length === 0) {
    return null;
  }

  const rateMultiplier = Math.max(0, Number(options.rateMultiplier || 1) || 0);
  const baseRate = explicitIds.length > 0 ? RARE_ENCOUNTER_RATE : getRareEncounterRateForRank(rank);
  const rate = Math.min(1, baseRate * rateMultiplier);
  if (options.force !== true && Math.random() >= rate) {
    return null;
  }

  return cloneMonsterData(candidates[Math.floor(Math.random() * candidates.length)]);
}

function getMonsterById(id) {
  const normalizedId = normalizeMonsterId(id);
  return normalizedId === null ? null : (ALL_MONSTER_BASES.find((monster) => monster.id === normalizedId) || null);
}

function getChestTrapById(id) {
  return cloneMonsterData(CHEST_TRAP_MONSTERS.find((monster) => monster.id === normalizeMonsterId(id)) || null);
}

function getChestTrapForFloor(floor) {
  const value = Math.max(1, Number(floor) || 1);
  const id = value >= 151 ? 120303 : value >= 101 ? 120302 : 120301;
  return getChestTrapById(id);
}

function getDeepFloorNormalBaseCandidates() {
  return NORMAL_MONSTER_BASES.filter((monster) => !monster.isBoss && !monster.isRare && !monster.isEstark && !monster.isSpecialBoss);
}

function generateEnemyForFloor(floor, options = {}) {
  const { allowRare = true } = options;

  if (allowRare) {
    const rare = tryGenerateRareMonster(floor);
    if (rare) return rare;
  }

  if (floor >= 1 && floor <= 200) {
    return generateBandMonster(floor);
  }

  return null;
}

function resolveMonsterImageDefinition(monsterOrId) {
  if (monsterOrId && typeof monsterOrId === 'object') return monsterOrId;
  const id = normalizeMonsterId(monsterOrId);
  return id !== null ? (getMonsterById(id) || { id }) : null;
}

function normalizeMonsterImageId(monsterOrId) {
  const monster = resolveMonsterImageDefinition(monsterOrId);
  const raw = monster ? (monster.imageId ?? monster.baseId ?? monster.id) : monsterOrId;
  const id = Number(raw);
  return Number.isFinite(id) && id > 0 ? Math.floor(id) : null;
}

function normalizeMonsterGraphicId(monsterOrId) {
  const monster = resolveMonsterImageDefinition(monsterOrId);
  const raw = monster ? (monster.baseId ?? monster.id) : monsterOrId;
  const id = Number(raw);
  return Number.isFinite(id) && id > 0 ? Math.floor(id) : null;
}

function getMonsterImagePath(monsterOrId) {
  const monster = typeof monsterOrId === 'object' && monsterOrId
    ? monsterOrId
    : getMonsterById(monsterOrId);
  const explicit = typeof monster?.image === 'string' && monster.image.trim()
    ? monster.image.trim()
    : (typeof monster?.img === 'string' && monster.img.trim() ? monster.img.trim() : '');
  if (explicit) return explicit;
  const imageId = normalizeMonsterImageId(monsterOrId);
  if (imageId === null) return null;
  const resolver = globalThis.PRISMA_ASSETS?.getMonsterImagePath;
  return (typeof resolver === 'function' && resolver !== getMonsterImagePath)
    ? resolver(monsterOrId)
    : `assets/monsters/monster_${formatMonsterId(imageId)}.webp`;
}

function getMonsterImageKey(monsterOrId) {
  const id = normalizeMonsterGraphicId(monsterOrId);
  if (id === null) return null;
  const resolver = globalThis.PRISMA_ASSETS?.getMonsterGraphicKey;
  return (typeof resolver === 'function' && resolver !== getMonsterImageKey)
    ? resolver(monsterOrId)
    : `monster_${id}`;
}

